const tableTitles = {
  students: "Students",
};
// ============================================================
// ONLINE STATUS
// ============================================================

async function loadOnlineStatus() {
  try {
    const response = await fetch(
      "https://guideplexlms.gsfcuniversity.in:8083/local/onlinestatus/api.php",
      {
        credentials: "include",
      }
    );

    const users = await response.json();

    users.forEach((user) => {
      const person = tableData1[group].find(
        (p) =>
          p.email &&
          user.email &&
          p.email.toLowerCase() === user.email.toLowerCase()
      );

      if (person) {
        person.status = true;
        person.lastAccess = user.lastAccess;
      }
    });

    renderTable();
  } catch (error) {
    console.error("API Error:", error);
    renderTable();
  }
}


// ============================================================
// ELEMENTS
// ============================================================

const tbody = document.querySelector("#userTable tbody");
const filterMenu = document.getElementById("filterMenu");
const searchInput = document.getElementById("tableSearch");


// Prevent clicks inside filter popup from closing it
filterMenu.addEventListener("click", (e) => {
  e.stopPropagation();
});


// ============================================================
// VARIABLES
// ============================================================

let currentColumn = null;

// Excel-style filters
const filters = {};

// Sorting
const sortState = {
  column: null,
  order: null, // "asc" or "desc"
};

// Pagination
let currentPage = 1;
let rowsPerPage = 25;

// Search
let searchText = "";


// ============================================================
// GET GROUP
// ============================================================

const params = new URLSearchParams(window.location.search);
const group = params.get("group");


// ============================================================
// INITIAL LOAD
// ============================================================

if (group && tableData1[group]) {
  document.getElementById("tableTitle").innerText =
    tableTitles[group];

  loadOnlineStatus();
}


// ============================================================
// GET COLUMN VALUE
// ============================================================

function getColumnValue(person, column) {
  if (column === "status") {
    return person.status ? "Online" : "Offline";
  }

  return person[column] ?? "";
}


// ============================================================
// SEARCH
// ============================================================

function applySearch(data) {
  if (!searchText.trim()) {
    return data;
  }

  const search = searchText.toLowerCase();

  return data.filter((person) => {

    return (
      (person.name || "").toLowerCase().includes(search) ||
      (person.enrolmentNo || "").toLowerCase().includes(search) ||
      (person.branch || "").toLowerCase().includes(search) ||
      (person.school || "").toLowerCase().includes(search) ||
      (person.email || "").toLowerCase().includes(search) ||
      (person.status ? "online" : "offline").includes(search) ||
      (person.lastAccess || "").toLowerCase().includes(search)
    );

  });
}


// ============================================================
// APPLY FILTERS
// ============================================================

function applyFilters(data, excludeColumn = null) {

  Object.keys(filters).forEach((column) => {

    if (column === excludeColumn) {
      return;
    }

    data = data.filter((person) => {

      const value = getColumnValue(person, column);

      return filters[column].includes(value);

    });

  });

  return data;
}


// ============================================================
// SORT
// ============================================================

function applySorting(data) {

  if (!sortState.column) {
    return data;
  }

  data.sort((a, b) => {

    const valueA = getColumnValue(
      a,
      sortState.column
    );

    const valueB = getColumnValue(
      b,
      sortState.column
    );

    const result = valueA
      .toString()
      .localeCompare(
        valueB.toString(),
        undefined,
        {
          numeric: true,
          sensitivity: "base",
        }
      );

    return sortState.order === "asc"
      ? result
      : -result;

  });

  return data;
}


// ============================================================
// RENDER TABLE
// ============================================================

function renderTable() {

  tbody.innerHTML = "";

  // ----------------------------------------------------------
  // STEP 1: ALL DATA
  // ----------------------------------------------------------

  let data = [...tableData1[group]];


  // ----------------------------------------------------------
  // STEP 2: SEARCH
  // ----------------------------------------------------------

  data = applySearch(data);


  // ----------------------------------------------------------
  // STEP 3: FILTER
  // ----------------------------------------------------------

  data = applyFilters(data);


  // ----------------------------------------------------------
  // STEP 4: SORT
  // ----------------------------------------------------------

  data = applySorting(data);


  // ----------------------------------------------------------
  // RECORD COUNTS
  // ----------------------------------------------------------

  const totalRecords =
    tableData1[group].length;

  const filteredRecords =
    data.length;


  // ----------------------------------------------------------
  // CLEAR ALL BUTTON
  // ----------------------------------------------------------

  const clearAllBtn =
    document.getElementById(
      "clearAllFilters"
    );

  const hasFilters =
    Object.keys(filters).length > 0;

  const hasSearch =
    searchText.trim() !== "";

  clearAllBtn.style.display =
    hasFilters || hasSearch
      ? "inline-block"
      : "none";


  // ----------------------------------------------------------
  // RECORD COUNT
  // ----------------------------------------------------------

  const recordCount =
    document.getElementById(
      "recordCount"
    );

  if (hasFilters || hasSearch) {

    recordCount.textContent =
      `Showing ${filteredRecords} of ${totalRecords} records`;

  } else {

    recordCount.textContent =
      `Total Records: ${totalRecords}`;

  }


  // ----------------------------------------------------------
  // PAGINATION
  // ----------------------------------------------------------

  const totalPages =
    Math.ceil(
      filteredRecords / rowsPerPage
    );


  // Prevent invalid page after filtering
  if (
    currentPage > totalPages &&
    totalPages > 0
  ) {
    currentPage = totalPages;
  }

  if (totalPages === 0) {
    currentPage = 1;
  }


  // ----------------------------------------------------------
  // GET CURRENT PAGE DATA
  // ----------------------------------------------------------

  const startIndex =
    (currentPage - 1) *
    rowsPerPage;

  const endIndex =
    startIndex + rowsPerPage;

  const pageData =
    data.slice(
      startIndex,
      endIndex
    );


  // ----------------------------------------------------------
  // RENDER ROWS
  // ----------------------------------------------------------

  pageData.forEach((person) => {

    tbody.innerHTML += `
      <tr>

        <td>
          ${person.name || ""}
        </td>

        <td>
          ${person.enrolmentNo || ""}
        </td>

        <td>
          ${person.branch || ""}
        </td>

        <td>
          ${person.school || ""}
        </td>

        <td>
          <span
            class="status ${
              person.status
                ? "online"
                : "offline"
            }"
          ></span>
        </td>

        <td>
          ${person.lastAccess || ""}
        </td>

      </tr>
    `;

  });


  // ----------------------------------------------------------
  // PAGINATION UI
  // ----------------------------------------------------------

  renderPagination(totalPages);
}


// ============================================================
// PAGINATION
// ============================================================

function renderPagination(totalPages) {

  const pagination =
    document.getElementById("pagination");

  pagination.innerHTML = "";

  if (totalPages <= 1) {
    return;
  }

  // -----------------------------
  // Previous button
  // -----------------------------

  const previousButton =
    document.createElement("button");

  previousButton.textContent = "‹";

  previousButton.disabled =
    currentPage === 1;

  previousButton.addEventListener("click", () => {

    if (currentPage > 1) {

      currentPage--;

      renderTable();
    }

  });

  pagination.appendChild(previousButton);


  // -----------------------------
  // Page button helper
  // -----------------------------

  function addPageButton(page) {

    const button =
      document.createElement("button");

    button.textContent = page;

    if (page === currentPage) {
      button.classList.add("active");
    }

    button.addEventListener("click", () => {

      currentPage = page;

      renderTable();

    });

    pagination.appendChild(button);
  }


  // -----------------------------
  // Ellipsis helper
  // -----------------------------

  function addEllipsis() {

    const span =
      document.createElement("span");

    span.textContent = "...";

    span.className = "pagination-ellipsis";

    pagination.appendChild(span);
  }


  // -----------------------------
  // Pagination logic
  // -----------------------------

  const maxVisiblePages = 5;

  // Small number of pages
  if (totalPages <= 7) {

    for (let page = 1; page <= totalPages; page++) {
      addPageButton(page);
    }

  }

  // Near beginning
  else if (currentPage <= 4) {

    for (let page = 1; page <= 5; page++) {
      addPageButton(page);
    }

    addEllipsis();

    addPageButton(totalPages);

  }

  // Near end
  else if (currentPage >= totalPages - 3) {

    addPageButton(1);

    addEllipsis();

    for (
      let page = totalPages - 4;
      page <= totalPages;
      page++
    ) {
      addPageButton(page);
    }

  }

  // Middle
  else {

    addPageButton(1);

    addEllipsis();

    for (
      let page = currentPage - 2;
      page <= currentPage + 2;
      page++
    ) {
      addPageButton(page);
    }

    addEllipsis();

    addPageButton(totalPages);

  }


  // -----------------------------
  // Next button
  // -----------------------------

  const nextButton =
    document.createElement("button");

  nextButton.textContent = "›";

  nextButton.disabled =
    currentPage === totalPages;

  nextButton.addEventListener("click", () => {

    if (currentPage < totalPages) {

      currentPage++;

      renderTable();
    }

  });

  pagination.appendChild(nextButton);
}

// ============================================================
// GET DATA FOR FILTER POPUP
// ============================================================

function getFilteredData(
  excludeColumn = null
) {

  let data =
    [...tableData1[group]];


  // Apply search
  data =
    applySearch(data);


  // Apply other filters
  data =
    applyFilters(
      data,
      excludeColumn
    );


  return data;
}


// ============================================================
// OPEN FILTER MENU
// ============================================================

function openFilterMenu(th) {

  const rect =
    th.getBoundingClientRect();


  // Position popup
  filterMenu.style.left =
    rect.left +
    window.scrollX +
    "px";

  filterMenu.style.top =
    rect.bottom +
    window.scrollY +
    "px";


  // ----------------------------------------------------------
  // GET UNIQUE VALUES
  // ----------------------------------------------------------

  const values = [
    ...new Set(

      getFilteredData(
        currentColumn
      ).map((person) => {

        return getColumnValue(
          person,
          currentColumn
        );

      })

    ),
  ]

    .filter(
      (value) =>
        value !== undefined &&
        value !== null
    )

    .sort((a, b) =>
      a
        .toString()
        .localeCompare(
          b.toString(),
          undefined,
          {
            numeric: true,
            sensitivity: "base",
          }
        )
    );


  // ----------------------------------------------------------
  // SELECT ALL
  // ----------------------------------------------------------

  const allSelected =
    !filters[currentColumn] ||
    values.every(
      (value) =>
        filters[currentColumn].includes(
          value
        )
    );


  // ----------------------------------------------------------
  // POPUP HTML
  // ----------------------------------------------------------

  filterMenu.innerHTML = `

    <button id="sortAsc">
      Sort A → Z
    </button>

    <button id="sortDesc">
      Sort Z → A
    </button>

    <hr>

    <input
      type="text"
      id="filterSearch"
      placeholder="Search..."
    >

    <div class="filter-values">

      <label>

        <input
          type="checkbox"
          id="selectAll"
          ${
            allSelected
              ? "checked"
              : ""
          }
        >

        <strong>
          Select All
        </strong>

      </label>

      <hr>

      ${values
        .map((value) => {

          const checked =
            !filters[currentColumn] ||
            filters[
              currentColumn
            ].includes(value);

          return `

            <label class="filter-item">

              <input
                type="checkbox"
                value="${value}"
                ${
                  checked
                    ? "checked"
                    : ""
                }
              >

              ${value}

            </label>

          `;

        })
        .join("")}

    </div>

    <button id="applyFilter">
      Apply
    </button>

    <button id="clearFilter">
      Clear
    </button>

  `;


  // ----------------------------------------------------------
  // FILTER SEARCH
  // ----------------------------------------------------------

  const filterSearch =
    document.getElementById(
      "filterSearch"
    );


  filterSearch.addEventListener(
    "input",
    () => {

      const search =
        filterSearch.value
          .toLowerCase();


      filterMenu
        .querySelectorAll(
          ".filter-item"
        )
        .forEach((item) => {

          const text =
            item.textContent
              .toLowerCase();


          item.style.display =
            text.includes(search)
              ? "flex"
              : "none";

        });

    }
  );


  // ----------------------------------------------------------
  // SORT ASC
  // ----------------------------------------------------------

  document
    .getElementById("sortAsc")
    .addEventListener(
      "click",
      () => {

        sortState.column =
          currentColumn;

        sortState.order =
          "asc";

        currentPage = 1;

        filterMenu.classList.add(
          "hidden"
        );

        renderTable();

      }
    );


  // ----------------------------------------------------------
  // SORT DESC
  // ----------------------------------------------------------

  document
    .getElementById("sortDesc")
    .addEventListener(
      "click",
      () => {

        sortState.column =
          currentColumn;

        sortState.order =
          "desc";

        currentPage = 1;

        filterMenu.classList.add(
          "hidden"
        );

        renderTable();

      }
    );


  filterMenu.classList.remove(
    "hidden"
  );


  // ----------------------------------------------------------
  // APPLY FILTER
  // ----------------------------------------------------------

  document
    .getElementById(
      "applyFilter"
    )
    .addEventListener(
      "click",
      () => {

        const checkedValues =
          Array.from(
            filterMenu.querySelectorAll(
              ".filter-item"
            )
          )

            .filter(
              (item) =>
                item.style.display !==
                "none"
            )

            .map(
              (item) =>
                item.querySelector(
                  "input"
                )
            )

            .filter(
              (input) =>
                input.checked
            )

            .map(
              (input) =>
                input.value
            );


        filters[
          currentColumn
        ] = checkedValues;


        // Go back to page 1
        currentPage = 1;


        filterMenu.classList.add(
          "hidden"
        );

        renderTable();

      }
    );


  // ----------------------------------------------------------
  // CLEAR CURRENT FILTER
  // ----------------------------------------------------------

  document
    .getElementById(
      "clearFilter"
    )
    .addEventListener(
      "click",
      () => {

        delete filters[
          currentColumn
        ];


        currentPage = 1;


        filterMenu.classList.add(
          "hidden"
        );

        renderTable();

      }
    );


  // ----------------------------------------------------------
  // SELECT ALL
  // ----------------------------------------------------------

  document
    .getElementById(
      "selectAll"
    )
    .addEventListener(
      "change",
      function () {

        const checked =
          this.checked;


        filterMenu
          .querySelectorAll(
            ".filter-item input"
          )
          .forEach(
            (checkbox) => {

              checkbox.checked =
                checked;

            }
          );

      }
    );
}


// ============================================================
// GLOBAL SEARCH BOX
// ============================================================

if (searchInput) {

  searchInput.addEventListener(
    "input",
    () => {

      searchText =
        searchInput.value;


      // Search should start from page 1
      currentPage = 1;


      renderTable();

    }
  );

}


// ============================================================
// CLOSE FILTER MENU
// ============================================================

document.addEventListener(
  "click",
  () => {

    filterMenu.classList.add(
      "hidden"
    );

  }
);


// ============================================================
// BACK BUTTON
// ============================================================

document
  .getElementById("backBtn")
  .addEventListener(
    "click",
    () => {

      window.location.href =
        "index.html";

    }
  );


// ============================================================
// HEADER FILTERS
// ============================================================

document
  .querySelectorAll(
    "#userTable th"
  )
  .forEach((th) => {

    th.addEventListener(
      "click",
      (e) => {

        currentColumn =
          th.dataset.column;

        openFilterMenu(th);

        e.stopPropagation();

      }
    );

  });


// ============================================================
// CLEAR ALL
// ============================================================

document
  .getElementById(
    "clearAllFilters"
  )
  .addEventListener(
    "click",
    () => {

      // Remove filters
      Object.keys(filters)
        .forEach(
          (key) =>
            delete filters[key]
        );


      // Remove sorting
      sortState.column = null;
      sortState.order = null;


      // Remove search
      searchText = "";

      if (searchInput) {
        searchInput.value = "";
      }


      // First page
      currentPage = 1;


      // Close popup
      filterMenu.classList.add(
        "hidden"
      );


      renderTable();

    }
  );


// ============================================================
// ROWS PER PAGE
// ============================================================

const rowsPerPageSelect =
  document.getElementById(
    "rowsPerPage"
  );


if (rowsPerPageSelect) {

  rowsPerPageSelect.addEventListener(
    "change",
    () => {

      rowsPerPage =
        parseInt(
          rowsPerPageSelect.value,
          10
        );


      currentPage = 1;


      renderTable();

    }
  );

}


// ============================================================
// REFRESH ONLINE STATUS
// ============================================================

setInterval(
  loadOnlineStatus,
  3000
);

